import{_ as o,o as e,c as p,a4 as s}from"./chunks/framework.DzJZdBQK.js";const u=JSON.parse('{"title":"写作课作业-070","description":"","frontmatter":{"date":"2020-09-27T22:28:49","title":"写作课作业-070","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[],"relativePath":"posts/homework/070.md","filePath":"posts/homework/070.md"}'),a={name:"posts/homework/070.md"};function r(c,t,_,l,n,i){return e(),p("div",null,[...t[0]||(t[0]=[s("<blockquote><p>9.27写作作业：《微信互联网平民创业》之《<strong>3.</strong> 微信给我们提供了什么？》 1.总结书中知识要点； 2.我对知识点的思考； 3.书中精彩的例子，可以用在其他什么地方； 4.书中用了排比、递进、转折吗？ 5.哪些知识点可以运用到自己学习、生活和工作中？</p></blockquote><blockquote><p>因为微信给你 —— 不仅给你，事实上是给每一个用户 —— 提供了一个竟然是免 费的却又可以⻓期打造、⻓期积累的「屏幕」(或者准确地讲，「广告屏幕」)</p><p>—— 那就是你每天可能看，也每天可能发的「朋友圈」</p></blockquote><p>如果没有看到朋友圈是个“广告屏”，我不会觉得它是，反而觉得利用朋友圈发广告的很烦人。但把它理解为“广告屏”时，看到别人发广告会有些变化，会去想怎么的人家文案好在哪里？</p><blockquote><p>朋友圈 &gt; 平面媒体</p><p>视频号 &gt; 微型电视台</p><p>直播号 &gt; 电视购物栏目</p></blockquote><blockquote><p>很多的时候，真的不是我们不努力，不是我们不勤奋，也不是我们不聪明，甚至不是我们不动脑，更不是我们没有脑子...... 只不过是我们「没看到」而已。一旦看到了，脑子 就会懂;脑子开始动并且不停地动，人就会变聪明;人变聪明了，就会开始琢磨;开始 琢磨了，就不可能不行动;开始行动了，就不可能不改变...... 就这么简单 —— 所有的 一切，「开眼」都是起点。所以古人总是说，「读万卷书不如行万里路」—— 行万里路 为什么竟然更有效啊?因为行万里路的过程中必然反复经历「开眼」，即，所谓的「⻓⻅识」。</p></blockquote><p>微信不断的打造赚钱通道，让微信成为一个赚钱工具，就如笑来老师一直在为践行群成员建立赚钱通道，让践行群成为赚钱的一样。一方面自己确实是“见识少”，但另一个问题是反思不够深入。这些天辅导儿子功课，被妻子问了一句话，你平时也在不断的学习，那有什么方法是可以传授给你儿子的呢？是反复么？是鼓励么？是耐心么？自己教孩子的时，很多时候是上火的，学到的东西哪些还用得上，就如儿子复习写字的要点都对，写的时候就天马行空了，居然控制不住自己。</p>",6)])])}const d=o(a,[["render",r]]);export{u as __pageData,d as default};
